from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            identity = ('id', event['id'])
            revision = event.get('revision', 0)
        else:
            identity = ('anonymous', position)
            revision = 0

        current = winners.get(identity)
        if current is None or revision >= current[0]:
            winners[identity] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(winners.values(), key=lambda winner: winner[1]):
        if event.get('void') is True:
            continue

        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}
